"""Simulation tasks with tractable joint log densities (for reference MCMC sampling)."""
import math
import numpy as np
import torch
from scipy.linalg import block_diag

LOG2PI = math.log(2 * math.pi)


def norm_lp(x, mu, sd):
    return -0.5 * ((x - mu) / sd) ** 2 - torch.log(torch.as_tensor(sd, dtype=x.dtype)) - 0.5 * LOG2PI


def unif_lp(x, lo, hi):
    inside = (x >= lo) & (x <= hi)
    return torch.where(inside, torch.full_like(x, -math.log(hi - lo)), torch.full_like(x, -float("inf")))


class Task:
    name = None
    d_theta = None
    d_x = None

    @property
    def d(self):
        return self.d_theta + self.d_x

    def sample_joint(self, n):  # returns (n, d) tensor [theta, x]
        th = self.sample_prior(n)
        return torch.cat([th, self.simulate(th)], -1)

    def log_joint(self, z):  # z (n, d)
        th, x = z[:, : self.d_theta], z[:, self.d_theta:]
        lp = self.log_prior(th)
        ll = self.log_lik(th, x)
        return torch.where(torch.isfinite(lp), lp + ll, lp)

    def directed_mask(self):
        raise NotImplementedError

    def undirected_mask(self):
        m = self.directed_mask().astype(bool)
        return (m | m.T | np.eye(self.d, dtype=bool))


class GaussianLinear(Task):
    name = "gaussian_linear"
    d_theta = 10
    d_x = 10

    def sample_prior(self, n):
        return torch.randn(n, 10) * math.sqrt(0.1)

    def simulate(self, th):
        return th + torch.randn_like(th) * math.sqrt(0.1)

    def log_prior(self, th):
        return norm_lp(th, 0.0, math.sqrt(0.1)).sum(-1)

    def log_lik(self, th, x):
        return norm_lp(x, th, math.sqrt(0.1)).sum(-1)

    def directed_mask(self):
        z = np.zeros((10, 10))
        return np.block([[np.eye(10), z], [np.eye(10), np.eye(10)]])

    def reference_posterior(self, x_o, n):
        # posterior N(x/2, 0.05 I)
        return x_o / 2 + torch.randn(n, 10) * math.sqrt(0.05)


class GaussianMixture(Task):
    name = "gaussian_mixture"
    d_theta = 2
    d_x = 2

    def sample_prior(self, n):
        return torch.rand(n, 2) * 20 - 10

    def simulate(self, th):
        s = torch.where(torch.rand(th.shape[0], 1) < 0.5, 1.0, 0.1)
        return th + s * torch.randn_like(th)

    def log_prior(self, th):
        return unif_lp(th, -10, 10).sum(-1)

    def log_lik(self, th, x):
        a = norm_lp(x, th, 1.0).sum(-1) + math.log(0.5)
        b = norm_lp(x, th, 0.1).sum(-1) + math.log(0.5)
        return torch.logaddexp(a, b)

    def directed_mask(self):
        return np.block([[np.eye(2), np.zeros((2, 2))], [np.ones((2, 2)), np.tril(np.ones((2, 2)))]])

    def reference_posterior(self, x_o, n):
        out = []
        while sum(o.shape[0] for o in out) < n:
            s = torch.where(torch.rand(4 * n, 1) < 0.5, 1.0, 0.1)
            th = x_o + s * torch.randn(4 * n, 2)
            ok = ((th > -10) & (th < 10)).all(-1)
            out.append(th[ok])
        return torch.cat(out)[:n]


class TwoMoons(Task):
    name = "two_moons"
    d_theta = 2
    d_x = 2

    def sample_prior(self, n):
        return torch.rand(n, 2) * 2 - 1

    def simulate(self, th):
        n = th.shape[0]
        a = (torch.rand(n) - 0.5) * math.pi
        r = 0.1 + 0.01 * torch.randn(n)
        p = torch.stack([r * torch.cos(a) + 0.25, r * torch.sin(a)], -1)
        off = torch.stack([-(th[:, 0] + th[:, 1]).abs() / math.sqrt(2), (-th[:, 0] + th[:, 1]) / math.sqrt(2)], -1)
        return p + off

    def log_prior(self, th):
        return unif_lp(th, -1, 1).sum(-1)

    def log_lik(self, th, x):
        u = x[:, 0] - 0.25 + (th[:, 0] + th[:, 1]).abs() / math.sqrt(2)
        v = x[:, 1] - (-th[:, 0] + th[:, 1]) / math.sqrt(2)
        r = torch.sqrt(u ** 2 + v ** 2) + 1e-12
        ll = norm_lp(r, 0.1, 0.01) - math.log(math.pi) - torch.log(r)
        return torch.where(u > 0, ll, torch.full_like(ll, -float("inf")))

    def directed_mask(self):
        return np.block([[np.eye(2), np.zeros((2, 2))], [np.ones((2, 2)), np.tril(np.ones((2, 2)))]])

    def reference_posterior(self, x_o, n):
        # exact sampling on a fine grid + uniform jitter within cells
        g = 1000
        c = (torch.arange(g, dtype=torch.float64) + 0.5) / g * 2 - 1
        T1, T2 = torch.meshgrid(c, c, indexing="ij")
        th = torch.stack([T1.flatten(), T2.flatten()], -1)
        lw = self.log_lik(th, x_o.double().expand(th.shape[0], 2))
        w = torch.softmax(lw, 0)
        idx = torch.multinomial(w.float(), n, replacement=True)
        return (th[idx] + (torch.rand(n, 2, dtype=torch.float64) - 0.5) * 2 / g).float()


class SLCP(Task):
    name = "slcp"
    d_theta = 5
    d_x = 8

    def sample_prior(self, n):
        return torch.rand(n, 5) * 6 - 3

    def _params(self, th):
        m = th[:, :2]
        s1, s2 = th[:, 2] ** 2, th[:, 3] ** 2
        rho = torch.tanh(th[:, 4])
        return m, s1, s2, rho

    def simulate(self, th):
        m, s1, s2, rho = self._params(th)
        n = th.shape[0]
        e1 = torch.randn(n, 4)
        e2 = torch.randn(n, 4)
        x1 = m[:, :1] + s1[:, None] * e1
        x2 = m[:, 1:2] + s2[:, None] * (rho[:, None] * e1 + torch.sqrt(1 - rho[:, None] ** 2) * e2)
        return torch.stack([x1, x2], -1).reshape(n, 8)

    def log_prior(self, th):
        return unif_lp(th, -3, 3).sum(-1)

    def log_lik(self, th, x):
        m, s1, s2, rho = self._params(th)
        x = x.reshape(-1, 4, 2)
        u = (x[..., 0] - m[:, :1]) / s1[:, None]
        v = (x[..., 1] - m[:, 1:2]) / s2[:, None]
        one_r2 = (1 - rho ** 2).clamp_min(1e-12)[:, None]
        q = (u ** 2 - 2 * rho[:, None] * u * v + v ** 2) / one_r2
        ll = -0.5 * q - LOG2PI - torch.log(s1 * s2 + 1e-30)[:, None] - 0.5 * torch.log(one_r2)
        return ll.sum(-1)

    def directed_mask(self):
        return np.block([[np.eye(5), np.zeros((5, 8))],
                         [np.ones((8, 5)), block_diag(*[np.tril(np.ones((2, 2))) for _ in range(4)])]])


class Tree(Task):
    name = "tree"
    d_theta = 3
    d_x = 4

    def sample_prior(self, n):
        t0 = torch.randn(n)
        return torch.stack([t0, t0 + torch.randn(n), t0 + torch.randn(n)], -1)

    def simulate(self, th):
        t1, t2 = th[:, 1], th[:, 2]
        n = th.shape[0]
        return torch.stack([torch.sin(t1) ** 2 + 0.2 * torch.randn(n), 0.1 * t1 ** 2 + 0.2 * torch.randn(n),
                            0.1 * t2 ** 2 + 0.6 * torch.randn(n), torch.cos(t2) ** 2 + 0.1 * torch.randn(n)], -1)

    def log_prior(self, th):
        return norm_lp(th[:, 0], 0., 1.) + norm_lp(th[:, 1], th[:, 0], 1.) + norm_lp(th[:, 2], th[:, 0], 1.)

    def log_lik(self, th, x):
        t1, t2 = th[:, 1], th[:, 2]
        return (norm_lp(x[:, 0], torch.sin(t1) ** 2, 0.2) + norm_lp(x[:, 1], 0.1 * t1 ** 2, 0.2)
                + norm_lp(x[:, 2], 0.1 * t2 ** 2, 0.6) + norm_lp(x[:, 3], torch.cos(t2) ** 2, 0.1))

    def directed_mask(self):
        # M[i, j] = 1 if variable i depends on (attends to) variable j
        m = np.eye(7)
        m[1, 0] = m[2, 0] = 1
        m[3, 1] = m[4, 1] = 1
        m[5, 2] = m[6, 2] = 1
        return m


class HMM(Task):
    name = "hmm"
    d_theta = 10
    d_x = 10

    def sample_prior(self, n):
        return torch.cumsum(0.5 * torch.randn(n, 10), -1)

    def simulate(self, th):
        return th ** 2 + 0.5 * torch.randn_like(th)

    def log_prior(self, th):
        prev = torch.cat([torch.zeros_like(th[:, :1]), th[:, :-1]], -1)
        return norm_lp(th, prev, 0.5).sum(-1)

    def log_lik(self, th, x):
        return norm_lp(x, th ** 2, 0.5).sum(-1)

    def directed_mask(self):
        z = np.zeros((10, 10))
        return np.block([[np.eye(10) + np.diag(np.ones(9), -1), z], [np.eye(10), np.eye(10)]])


TASKS = {c.name: c for c in [GaussianLinear, GaussianMixture, TwoMoons, SLCP, Tree, HMM]}


@torch.no_grad()
